def free_slots(limit, busy):
    if limit <= 0:
        return []

    busy_intervals = sorted(busy)
    free_intervals = []

    for start, end in busy_intervals:
        if not free_intervals or start > free_intervals[-1][1]:
            free_intervals.append([start, end])
        else:
            free_intervals[-1][1] = max(free_intervals[-1][1], end)

    return free_intervals

def shortest_span(values, threshold):
    if not values:
        return 0

    n = len(values)
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + values[i]

    min_span = float('inf')
    for i in range(n):
        for j in range(i, n):
            if prefix_sums[j + 1] - prefix_sums[i] >= threshold:
                min_span = min(min_span, j - i + 1)

    return min_span if min_span != float('inf') else 0

def build_layers(n, prerequisites):
    graph = [[] for _ in range(n)]
    in_degree = [0] * n
    for a, b in prerequisites:
        graph[a].append(b)
        in_degree[b] += 1

    def topological_sort():
        queue = [i for i in range(n) if in_degree[i] == 0]
        layers = []
        while queue:
            layer = []
            for _ in range(len(queue)):
                node = queue.pop(0)
                layer.append(node)
                for neighbor in graph[node]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        queue.append(neighbor)
            layers.append(layer)
        return layers if len(layers) == 1 else []

    return topological_sort()

def top_words(words, k):
    if k <= 0:
        return []
    word_counts = {}
    for word in words:
        word_counts[word] = word_counts.get(word, 0) + 1
    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))
    return [word for word, count in sorted_words[:k]]

