import sys

def main():
    inventory = {}
    for line in sys.stdin:
        command, name = line.strip().split()
        if command == "PUT":
            inventory[name] = inventory.get(name, 0) + 1
        elif command == "TAKE":
            if name in inventory and inventory[name] > 0:
                inventory[name] -= 1
        elif command == "QUERY":
            if name in inventory:
                print(inventory[name], end="")
            else:
                print("0", end="")
        print()

if __name__ == "__main__":
    main()
